class GomokuGame:
    WHITE_SPACE = ' '
    SYMBOL_X = 'X'
    SYMBOL_O = 'O'
    FIVE_IN_A_ROW = 5

    def __init__(self, board_size):
        self._board_size = board_size
        self._board = [[self.WHITE_SPACE for _ in range(board_size)] for _ in range(board_size)]
        self._current_player = self.SYMBOL_X

    @property
    def board_size(self):
        return self._board_size

    @property
    def board(self):
        return [row[:] for row in self._board]

    @property
    def current_player(self):
        return self._current_player

    @current_player.setter
    def current_player(self, value):
        if value not in (self.SYMBOL_X, self.SYMBOL_O):
            raise ValueError("Current player must be 'X' or 'O'")
        self._current_player = value

    def make_move(self, row, col):
        if self._is_valid_move(row, col):
            self._board[row][col] = self._current_player
            self._switch_player()
            return True
        return False

    def _is_valid_move(self, row, col):
        return self._board[row][col] == self.WHITE_SPACE

    def _switch_player(self):
        self._current_player = self.SYMBOL_O if self._current_player == self.SYMBOL_X else self.SYMBOL_X

    def check_winner(self):
        directions = [(0, 1), (1, 0), (1, 1), (1, -1)]
        for row in range(self._board_size):
            for col in range(self._board_size):
                symbol = self._board[row][col]
                if symbol != self.WHITE_SPACE:
                    for direction in directions:
                        if self._check_five_in_a_row(row, col, direction):
                            return symbol
        return None

    def _check_five_in_a_row(self, row, col, direction):
        dx, dy = direction
        symbol = self._board[row][col]
        return self._count_in_direction(row, col, dx, dy, symbol) == self.FIVE_IN_A_ROW

    def _count_in_direction(self, row, col, dx, dy, symbol):
        count = 1
        for i in range(1, self.FIVE_IN_A_ROW):
            new_row = row + dx * i
            new_col = col + dy * i
            if not self._is_in_bounds(new_row, new_col):
                return count
            if self._board[new_row][new_col] == symbol:
                count += 1
            else:
                break
        return count

    def _is_in_bounds(self, row, col):
        return 0 <= row < self._board_size and 0 <= col < self._board_size
